// Mock helper for desktop runtime smoke tests.
import Foundation

func getEnv(_ key: String) -> String? {
    ProcessInfo.processInfo.environment[key]
}

func readStarts(_ path: String) -> Int {
    if let content = try? String(contentsOfFile: path, encoding: .utf8),
       let n = Int(content.trimmingCharacters(in: .whitespacesAndNewlines)) {
        return n
    }
    return 0
}

func writeStarts(_ path: String, count: Int) {
    try? "\(count)".write(toFile: path, atomically: true, encoding: .utf8)
}

func countStarts(_ prefix: String, key: String) -> Int {
    let p = prefix + key
    let n = readStarts(p) + 1
    writeStarts(p, count: n)
    return n
}

let pngBase64 = "iVBORw0KGgoAAAANSUhEUgAAA7YAAAKoCAIAAMwz9JAMAAAATkVYSWZNTQAqAAAACAAFARIAAwAAAAEAAQAAARoAAwAAAAEBAAAFAQAEAAAAPAAAABYAAQAEAAAAOwAAABcAAQAEAAAAOwAAAAAAAADyAAAAPAAAAPEAAAA8AAAC204KAAA="

// 950x680 PNG minimal data
func writePng(to path: String) {
    // 3230 bytes 950x680 PNG generated by zlib
    let hex = """
    
    """
    var data = Data()
    var idx = hex.startIndex
    while idx < hex.endIndex {
        let nextIdx = hex.index(idx, offsetBy: 2, limitedBy: hex.endIndex) ?? hex.endIndex
        let byteStr = String(hex[idx..<nextIdx]).trimmingCharacters(in: .whitespacesAndNewlines)
        if let byte = UInt8(byteStr, radix: 16) {
            data.append(byte)
        }
        idx = nextIdx
    }
    try? data.write(to: URL(fileURLWithPath: path))
}

func runHelper() {
    let startsPath = getEnv("HELPER_STARTS") ?? "/tmp/starts"
    let currentStarts = readStarts(startsPath) + 1
    writeStarts(startsPath, count: currentStarts)

    let overlayStatePath = getEnv("OVERLAY_STATE")
    let clicksPath = getEnv("HELPER_CLICKS")
    let mode = getEnv("HELPER_CASE") ?? "normal"

    var sequence = 0
    var searchReads = 0

    while let line = readLine() {
        if line.isEmpty { continue }
        guard let data = line.data(using: .utf8),
              let req = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
              let reqId = req["id"] as? Int else {
            continue
        }

        if let osp = overlayStatePath,
           let state = try? String(contentsOfFile: osp, encoding: .utf8) {
            let trimmed = state.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty && trimmed != "hide" {
                fputs("overlay visible during native capture: \(trimmed)\n", stderr)
                exit(1)
            }
        }

        sequence += 1
        var result: [String: Any] = [
            "protocol_version": 1,
            "id": reqId,
            "ok": true
        ]

        if mode == "wrong_id" {
            result["id"] = reqId + 100
        } else if mode == "failed" {
            result["ok"] = false
            result["error"] = "capture_unavailable"
        } else if mode == "oversized" {
            let big = String(repeating: "x", count: 4 * 1024 * 1024 + 10)
            print(big)
            fflush(stdout)
            continue
        } else {
            func textItem(_ value: String, _ x: Double, _ y: Double) -> [String: Any] {
                [
                    "text": value,
                    "bounds": ["x": x, "y": y, "width": 0.15, "height": 0.03],
                    "confidence": 0.95
                ]
            }

            let params = req["params"] as? [String: Any] ?? [:]
            let region = params["region"] as? String ?? ""

            var lines = [
                textItem("Alice", 0.1, 0.1),
                textItem("12:00", 0.8, 0.1),
                textItem("preview", 0.1, 0.14)
            ]

            if region == "chat" {
                lines = [textItem("收到", 0.1, 0.1), textItem("收到", 0.1, 0.3)]
            }
            if region == "title" {
                lines = [textItem("Alice", 0.1, 0.1)]
            }

            if (mode.hasPrefix("search_") || mode == "duplicate_target") && region == "title" {
                var clicked = 0
                if let cp = clicksPath, let cContent = try? String(contentsOfFile: cp, encoding: .utf8) {
                    clicked = cContent.components(separatedBy: .newlines).filter { !$0.isEmpty }.count
                }
                lines = [textItem(clicked >= 2 ? "Alice" : "Other", 0.1, 0.1)]
            }

            if mode.hasPrefix("search_") {
                if region == "search" {
                    searchReads += 1
                    let word = (searchReads == 1) ? "搜索" : (mode == "search_success" ? "Alice" : "Wrong")
                    lines = [textItem(word, 0.1, 0.1)]
                } else if region == "sessions" && searchReads < 2 {
                    lines = [textItem("Other", 0.1, 0.1)]
                }
            }

            if mode == "duplicate_target" && region == "sessions" {
                lines = [textItem("Alice", 0.1, 0.1), textItem("Alice", 0.1, 0.4)]
            }

            if mode == "blank_window" {
                lines = []
            }

            var winObj: [String: Any] = [
                "window_id": 1,
                "pid": 123,
                "x": 0,
                "y": 0,
                "width": 950,
                "height": 680,
                "on_screen": true
            ]
            if mode == "changed_window" {
                winObj["window_id"] = 2
            }

            if mode == "bad_bounds" && !lines.isEmpty {
                var b = lines[0]["bounds"] as! [String: Any]
                b["width"] = 2
                lines[0]["bounds"] = b
            }

            let resObj: [String: Any] = [
                "epoch": "fixture-epoch",
                "sequence": sequence,
                "window": winObj,
                "region": ["x": 0.05, "y": 0.1, "width": 0.25, "height": 0.8],
                "digest": String(repeating: "a", count: 64),
                "captured_at_ms": 1000,
                "ocr_cached": sequence > 1,
                "lines": lines,
                "title_lines": [textItem("Alice", 0.1, 0.1)]
            ]
            result["result"] = resObj
        }

        if let outData = try? JSONSerialization.data(withJSONObject: result),
           let outStr = String(data: outData, encoding: .utf8) {
            print(outStr)
            fflush(stdout)
        }
    }
}

func runOverlay() {
    let statePath = getEnv("OVERLAY_STATE")
    let eventsPath = getEnv("OVERLAY_EVENTS")

    while let line = readLine() {
        if line.isEmpty { continue }
        guard let data = line.data(using: .utf8),
              let req = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
              let event = req["event"] as? String else {
            continue
        }

        if let sp = statePath {
            try? event.write(toFile: sp, atomically: true, encoding: .utf8)
        }
        if let ep = eventsPath {
            if let handle = FileHandle(forWritingAtPath: ep) {
                handle.seekToEndOfFile()
                if let evData = "\(event)\n".data(using: .utf8) {
                    handle.write(evData)
                }
                handle.closeFile()
            } else {
                try? "\(event)\n".write(toFile: ep, atomically: true, encoding: .utf8)
            }
        }
        print("{\"ok\":true}")
        fflush(stdout)
    }
}

func runLegacyOcr(_ imgPath: String) {
    let mode = getEnv("HELPER_CASE") ?? "legacy_success"
    let prefix = getEnv("HELPER_STARTS") ?? "/tmp/starts"
    let clicksPath = getEnv("HELPER_CLICKS")

    var text = "visible text"
    if imgPath.contains("search") {
        let idx = countStarts(prefix, key: "search")
        text = (idx == 1) ? "Q 搜察" : (mode == "legacy_query_mismatch" ? "Wrong" : "Alice")
    } else if imgPath.contains("list") {
        let idx = countStarts(prefix, key: "list")
        text = (idx == 1) ? "Other" : "Alice"
    } else if imgPath.contains("title") {
        var clicked = 0
        if let cp = clicksPath, let cContent = try? String(contentsOfFile: cp, encoding: .utf8) {
            clicked = cContent.components(separatedBy: .newlines).filter { !$0.isEmpty }.count
        }
        text = (clicked >= 2) ? "Alice" : "Other"
    }

    var items: [[String: Any]] = [
        ["text": text, "x": 0.1, "y": 0.1]
    ]

    if mode == "legacy_duplicate" && imgPath.contains("list") && text == "Alice" {
        items.append(["text": "Alice", "x": 0.1, "y": 0.4])
    }

    if let data = try? JSONSerialization.data(withJSONObject: items),
       let s = String(data: data, encoding: .utf8) {
        print(s)
    }
}

func runLegacyCapture(_ outPath: String) {
    if let sp = getEnv("OVERLAY_STATE"),
       let state = try? String(contentsOfFile: sp, encoding: .utf8) {
        let trimmed = state.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty && trimmed != "hide" {
            fputs("overlay visible during screen capture: \(trimmed)\n", stderr)
            exit(1)
        }
    }
    writePng(to: outPath)
}

@main
struct DesktopSmokeMain {
    static func main() {
        let args = CommandLine.arguments
        guard args.count >= 2 else {
            fputs("usage: desktop_smoke_selftest <helper|overlay|legacy_ocr|legacy_capture> [args...]\n", stderr)
            exit(1)
        }
        let cmd = args[1]
        switch cmd {
        case "helper":
            runHelper()
        case "overlay":
            runOverlay()
        case "legacy_ocr":
            let img = args.count >= 3 ? args[2] : ""
            runLegacyOcr(img)
        case "legacy_capture":
            let out = args.count >= 3 ? args[2] : "/tmp/out.png"
            runLegacyCapture(out)
        default:
            fputs("unknown subcommand: \(cmd)\n", stderr)
            exit(1)
        }
    }
}
